private Dictionary<string, DataTable> GetDashboardData(
    string scienceId,
    string courseId,
    string classId,
    int yearId,
    byte semester)
{
    Dictionary<string, DataTable> dicResult = LoadDashboardDataSingleCall(
        scienceId,
        courseId,
        classId,
        yearId,
        semester);

    if (dicResult != null)
        return dicResult;

    return LoadDashboardDataLegacy(
        scienceId,
        courseId,
        classId,
        yearId,
        semester);
}

private Dictionary<string, DataTable> LoadDashboardDataSingleCall(
    string scienceId,
    string courseId,
    string classId,
    int yearId,
    byte semester)
{
    string strConnection = ResolveConnectionString();
    if (strConnection == null || strConnection == "")
        return null;

    string[] arrKeys = new string[]
    {
        "summary",
        "byLevel",
        "byClass",
        "byScience",
        "byCourse",
        "levelByScience",
        "markRange",
        "evalStatus"
    };

    DataSet dsData = new DataSet();
    SqlConnection objConn = null;
    try
    {
        objConn = new SqlConnection(strConnection);
        objConn.Open();

        SqlCommand objCmd = new SqlCommand(SP_DATA, objConn);
        objCmd.CommandType = CommandType.StoredProcedure;
        objCmd.CommandTimeout = 120;
        AddDashboardParameters(objCmd, scienceId, courseId, classId, yearId, semester, DBNull.Value);

        SqlDataAdapter objAdapter = new SqlDataAdapter(objCmd);
        objAdapter.Fill(dsData);
    }
    catch (Exception)
    {
        return null;
    }
    finally
    {
        if (objConn != null)
        {
            if (objConn.State == ConnectionState.Open)
                objConn.Close();
            objConn.Dispose();
        }
    }

    if (dsData.Tables.Count < arrKeys.Length)
        return null;

    Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
    int intIndex;
    for (intIndex = 0; intIndex < arrKeys.Length; intIndex++)
        dicResult[arrKeys[intIndex]] = dsData.Tables[intIndex];

    return dicResult;
}

private Dictionary<string, DataTable> LoadDashboardDataLegacy(
    string scienceId,
    string courseId,
    string classId,
    int yearId,
    byte semester)
{
    Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
    SIM_SummaryEthicMark objEthic = new SIM_SummaryEthicMark();

    dicResult["summary"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 1);
    dicResult["byLevel"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 2);
    dicResult["byClass"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 3);
    dicResult["byScience"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 4);
    dicResult["byCourse"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 5);
    dicResult["levelByScience"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 6);
    dicResult["markRange"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 7);
    dicResult["evalStatus"] = CallResultSet(objEthic, scienceId, courseId, classId, yearId, semester, 8);

    return dicResult;
}

private void AddDashboardParameters(
    SqlCommand objCmd,
    string scienceId,
    string courseId,
    string classId,
    int yearId,
    byte semester,
    object resultSet)
{
    objCmd.Parameters.Add("@ScienceID", SqlDbType.NVarChar, 50).Value = NormalizeFilter(scienceId);
    objCmd.Parameters.Add("@CourseID", SqlDbType.NVarChar, 50).Value = NormalizeFilter(courseId);
    objCmd.Parameters.Add("@ClassID", SqlDbType.NVarChar, 50).Value = NormalizeFilter(classId);
    objCmd.Parameters.Add("@YearID", SqlDbType.Int).Value = yearId;
    objCmd.Parameters.Add("@Semester", SqlDbType.TinyInt).Value = semester;
    objCmd.Parameters.Add("@ResultSet", SqlDbType.TinyInt).Value = resultSet;
}

private string ResolveConnectionString()
{
    ConnectionStringSettings objSetting = ConfigurationManager.ConnectionStrings["DefaultConnectionString2"];
    if (objSetting != null && objSetting.ConnectionString != null && objSetting.ConnectionString != "")
        return objSetting.ConnectionString;

    objSetting = ConfigurationManager.ConnectionStrings["DefaultConnectionString"];
    if (objSetting != null && objSetting.ConnectionString != null && objSetting.ConnectionString != "")
        return objSetting.ConnectionString;

    return null;
}

private DataTable CallResultSet(
    SIM_SummaryEthicMark objEthic,
    string scienceId,
    string courseId,
    string classId,
    int yearId,
    byte semester,
    byte resultSet)
{
    return objEthic.GetDataTable(
        SP_DATA,
        "@ScienceID", NormalizeFilter(scienceId),
        "@CourseID", NormalizeFilter(courseId),
        "@ClassID", NormalizeFilter(classId),
        "@YearID", yearId,
        "@Semester", semester,
        "@ResultSet", resultSet);
}

