/*
    Benchmark tốc độ dashboard Rèn luyện — DASH_StudentEthic_GetData
    Chạy trên SQL Server có dữ liệu thật (SSMS / sqlcmd).

    So sánh:
      A) 8 lần gọi riêng (@ResultSet = 1..8) — giống API hiện tại
      B) 1 lần gọi (@ResultSet = NULL) — build temp table 1 lần
      C) Đếm nguồn dữ liệu thực tế (SV active vs SV có bản ghi RL)
*/

SET NOCOUNT ON;

Declare @YearID int = 2025;
Declare @Semester tinyint = 1;
Declare @ScienceID nvarchar(50) = NULL;
Declare @CourseID nvarchar(50) = NULL;
Declare @ClassID nvarchar(50) = NULL;

Declare @Start datetime2;
Declare @End datetime2;
Declare @ElapsedMs int;
Declare @i tinyint;
Declare @Total8 int = 0;
Declare @ActiveStudent int;
Declare @EthicRecord int;
Declare @EvaluatedStudent int;

Print '========================================';
Print 'DASH_StudentEthic_GetData — Benchmark';
Print 'YearID=' + Cast(@YearID as varchar(10)) + ', Semester=' + Cast(@Semester as varchar(10));
Print '========================================';

/* Thống kê nguồn — xác định bottleneck */
Select
    @ActiveStudent = Count(*)
From SIM_Student
    Inner Join SIM_Class On SIM_Class.ClassID = SIM_Student.ClassID
Where SIM_Student.IsDeleted = 0
    And SIM_Student.Status > 0
    And SIM_Student.Status < 3
    And SIM_Class.IsActived = 1
    And SIM_Class.ClassType = 0
    And (@ClassID is null or @ClassID = N'' or SIM_Student.ClassID = @ClassID)
    And (@ScienceID is null or @ScienceID = N'' or SIM_Class.ScienceID = @ScienceID)
    And (@CourseID is null or @CourseID = N'' or SIM_Class.CourseID = @CourseID);

Select
    @EthicRecord = Count(*)
From SIM_SummaryEthicMark
Where YearID = @YearID;

Select
    @EvaluatedStudent = Count(*)
From SIM_Student
    Inner Join SIM_Class On SIM_Class.ClassID = SIM_Student.ClassID
    Left Join SIM_SummaryEthicMark tblEthic On tblEthic.StudentID = SIM_Student.StudentID
        And tblEthic.YearID = @YearID
Where SIM_Student.IsDeleted = 0
    And SIM_Student.Status > 0
    And SIM_Student.Status < 3
    And SIM_Class.IsActived = 1
    And SIM_Class.ClassType = 0
    And (@ClassID is null or @ClassID = N'' or SIM_Student.ClassID = @ClassID)
    And (@ScienceID is null or @ScienceID = N'' or SIM_Class.ScienceID = @ScienceID)
    And (@CourseID is null or @CourseID = N'' or SIM_Class.CourseID = @CourseID)
    And (
        (@Semester = 1 And tblEthic.EthicMark1 is not null)
        Or (@Semester = 2 And tblEthic.EthicMark2 is not null)
        Or (@Semester not in (1, 2) And tblEthic.EthicMark is not null)
    );

Print '';
Print '--- Nguồn dữ liệu ---';
Print 'SV active (SP quét mỗi lần gọi)     : ' + Cast(@ActiveStudent as varchar(20));
Print 'Bản ghi SIM_SummaryEthicMark (Year)  : ' + Cast(@EthicRecord as varchar(20));
Print 'SV đã có điểm RL (HK ' + Cast(@Semester as varchar(2)) + ')           : ' + Cast(@EvaluatedStudent as varchar(20));
Print 'Tỷ lệ quét thừa                    : ' +
    Case
        when @ActiveStudent = 0 then 'N/A'
        else Cast(Cast((@ActiveStudent - @EvaluatedStudent) * 100.0 / @ActiveStudent as decimal(10, 1)) as varchar(20)) + '%'
    End;

/* A) 8 lần gọi — mô phỏng StudentEthicDashboardApi.ashx */
Print '';
Print '--- A) 8 lần gọi @ResultSet = 1..8 (API hiện tại) ---';

Set @Start = SYSDATETIME();
Set @i = 1;
While @i <= 8
Begin
    Exec dbo.DASH_StudentEthic_GetData
        @ScienceID = @ScienceID,
        @CourseID = @CourseID,
        @ClassID = @ClassID,
        @YearID = @YearID,
        @Semester = @Semester,
        @ResultSet = @i;
    Set @i = @i + 1;
End;
Set @End = SYSDATETIME();
Set @Total8 = Datediff(millisecond, @Start, @End);
Print 'Tổng thời gian 8 lần gọi (ms)      : ' + Cast(@Total8 as varchar(20));
Print 'Trung bình mỗi lần (ms)            : ' + Cast(@Total8 / 8 as varchar(20));

/* B) 1 lần gọi tất cả result set */
Print '';
Print '--- B) 1 lần gọi @ResultSet = NULL ---';

Set @Start = SYSDATETIME();
Exec dbo.DASH_StudentEthic_GetData
    @ScienceID = @ScienceID,
    @CourseID = @CourseID,
    @ClassID = @ClassID,
    @YearID = @YearID,
    @Semester = @Semester,
    @ResultSet = NULL;
Set @End = SYSDATETIME();
Set @ElapsedMs = Datediff(millisecond, @Start, @End);
Print 'Tổng thời gian 1 lần gọi (ms)      : ' + Cast(@ElapsedMs as varchar(20));

/* C) Từng result set riêng lẻ */
Print '';
Print '--- C) Chi tiết từng ResultSet (ms) ---';

Set @i = 1;
While @i <= 8
Begin
    Set @Start = SYSDATETIME();
    Exec dbo.DASH_StudentEthic_GetData
        @ScienceID = @ScienceID,
        @CourseID = @CourseID,
        @ClassID = @ClassID,
        @YearID = @YearID,
        @Semester = @Semester,
        @ResultSet = @i;
    Set @End = SYSDATETIME();
    Set @ElapsedMs = Datediff(millisecond, @Start, @End);
    Print 'ResultSet ' + Cast(@i as varchar(2)) + ' : ' + Cast(@ElapsedMs as varchar(20)) + ' ms';
    Set @i = @i + 1;
End;

Print '';
Print '--- Kết luận nhanh ---';
Print 'Nếu A >> B  => bottleneck là gọi SP 8 lần (build temp table lặp lại).';
Print 'Nếu B vẫn chậm => bottleneck là quét toàn bộ SIM_Student (~' + Cast(@ActiveStudent as varchar(20)) + ' dòng).';
Print 'Đổi KPI Tổng SV -> Nhóm lớp KHÔNG giảm A hay B vì cùng nguồn #tblEthicView.';
